from random import random

class LimitedSet:
    def __init__(self, capacity: int, initial_elements: List = []):
        self.capacity = capacity
        self.elements = initial_elements[:capacity]

    def add(self, element: Any) -> Any:
        if len(self.elements) < self.capacity:
            self.elements.append(element)
        else:
            if random() < self.capacity / len(self.elements):
                index_to_replace = int(random() * self.capacity)
                self.elements[index_to_replace] = element
        return self.elements

