import os

def file_manipulation(path: str, new_dir: str, ext: str) -> None:
    if not os.path.exists(os.path.join(path, new_dir)):
        os.mkdir(os.path.join(path, new_dir))

    files_to_move = [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f)) and f != new_dir and f.endswith('.' + ext)]

    for file in files_to_move:
        new_path = os.path.join(path, new_dir, file)
        if os.path.exists(new_path):
            count = 1
            while True:
                new_path = os.path.join(path, new_dir, f"{os.path.splitext(file)[0]}_{count}.{ext}")
                if not os.path.exists(new_path):
                    break
                count += 1
        os.rename(os.path.join(path, file), new_path)
