class InputDataNotConvertibleExc(Exception):
    pass

class InputDataTypeNotInAllowlistExc(Exception):
    pass

class IntegerBlueprint:
    def __init__(self, parsing_mode):
        self.parsing_mode = parsing_mode

    def validate(self, data):
        if self.parsing_mode == ParsingMode.MODE_STRICT:
            try:
                return int(data)
            except (ValueError, TypeError):
                raise InputDataNotConvertibleExc
        else:
            raise NotImplementedError("Parsing mode not supported")

class ListBlueprint:
    def __init__(self, item_blueprint, parsing_mode):
        self.item_blueprint = item_blueprint
        self.parsing_mode = parsing_mode

    def validate(self, data):
        if not isinstance(data, list):
            raise InputDataNotConvertibleExc
        validated_data = []
        for item in data:
            validated_item = self.item_blueprint.validate(item)
            validated_data.append(validated_item)
        return validated_data

class ParsingMode:
    MODE_STRICT = "strict"

class IterableObject:
    def __init__(self, data):
        self.data = data

    def validate(self, allowlist=None):
        if not all(isinstance(item, allowlist) for item in self.data):
            raise InputDataTypeNotInAllowlistExc
        return self.data

class ExceptionRaisingIterableObject:
