import os

def xdg_home():
    """Return the absolute path of the user's home directory based on the XDG Base Directory Specification."""
    xdg_home_env = os.getenv('XDG_HOME')
    if xdg_home_env:
        return os.path.expanduser(xdg_home_env)
    else:
        return os.path.expanduser("~")

def environ_paths(env_variable):
    """Return a list of paths specified in the given environment variable."""
    paths = os.getenv(env_variable)
    if paths:
        return paths.split(':')
    else:
        return []

def resolve_file_path(filename):
    """Resolve the absolute path of the given file based on the XDG Base Directory Specification."""
    xdg_config_dirs = environ_paths("XDG_CONFIG_DIRS")
    xdg_homes = [xdg_home()]
    for directory in xdg_config_dirs + xdg_homes:
        file_path = os.path.join(directory, filename)
        if os.path.exists(file_path):
            return file_path
    return None
```
