from PyQt5.QtCore import QAbstractTableModel, QModelIndex, Qt

class CustomDataModel(QAbstractTableModel):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.mydata = []

    def rowCount(self, parent=QModelIndex()):
        return len(self.mydata)

    def columnCount(self, parent=QModelIndex()):
        return 2  # Assuming each row has 2 columns (name and value)

    def data(self, index, role=Qt.DisplayRole):
        if role == Qt.DisplayRole:
            row = index.row()
            col = index.column()
            if 0 <= row < len(self.mydata) and 0 <= col < 2:
                return self.mydata[row][col]
        return None

    def addRow(self, name, value):
        self.beginInsertRows(QModelIndex(), len(self.mydata), len(self.mydata))
        self.mydata.append([name, value])
        self.endInsertRows()

    def removeRows(self, rowIndexes):
        for row in sorted(rowIndexes, reverse=True):
            self.beginRemoveRows(QModelIndex(), row, row)
            del self.mydata[row]
            self.endRemoveRows()
```

