        self.text = text

class Cell:
    def __init__(self, tokens, rowspan, colspan):
        self.tokens = tokens
        self.rowspan = rowspan
        self.colspan = colspan

class Table:
    def __init__(self, nrow, ncol):
        self.nrow = nrow
        self.ncol = ncol
        self.table = [['' for _ in range(ncol)] for _ in range(nrow)]

    @classmethod
    def create_from_cells(cls, cells):
        max_row = max(sum(cell.rowspan for cell in cells), len(cells))
        max_col = max(sum(cell.colspan for cell in cells), max(len(cell.tokens) for cell in cells))

        table = [['' for _ in range(max_col)] for _ in range(max_row)]

        row, col = 0, 0
        for cell in cells:
            while table[row][col]:
                col += 1
                if col == max_col:
                    col = 0
                    row += 1

            for i in range(cell.rowspan):
                for j in range(cell.colspan):
                    if i == 0 and j == 0:
                        table[row + i][col + j] = cell.tokens[0].text
                    else:
                        table[row + i][col + j] = ''

        return table
```

