def mergeSortedArrays(sorted_output1, sorted_output2):
    merged_array = []
    i, j = 0, 0

    while i < len(sorted_output1) and j < len(sorted_output2):
        if sorted_output1[i] < sorted_output2[j]:
            merged_array.append(sorted_output1[i])
            i += 1
        else:
            merged_array.append(sorted_output2[j])
            j += 1

    while i < len(sorted_output1):
        merged_array.append(sorted_output1[i])
        i += 1

    while j < len(sorted_output2):
        merged_array.append(sorted_output2[j])
        j += 1

    return merged_array
