def find_files_by_extension(directory_path: str, file_extension: str) -> Union[List[str], str]:
    if not os.path.exists(directory_path) or not os.path.isdir(directory_path):
        return "Invalid directory path"

    matching_files = []
    for root, _, files in os.walk(directory_path):
        for file in files:
            if file.endswith(f".{file_extension}"):
                matching_files.append(os.path.relpath(os.path.join(root, file), directory_path))

    if len(matching_files) == 0:
        return f"There are no {file_extension} files in the location of {directory_path}"
    else:
        return matching_files
```

