class Linear:
    def __init__(self, slope, intercept):
        self.slope = slope
        self.intercept = intercept

    def add(self, other):
        new_slope = self.slope + other.slope
        new_intercept = self.intercept + other.intercept
        return Linear(new_slope, new_intercept)

    def subtract(self, other):
        new_slope = self.slope - other.slope
        new_intercept = self.intercept - other.intercept
        return Linear(new_slope, new_intercept)

    def multiply(self, scalar):
        new_slope = self.slope * scalar
        new_intercept = self.intercept * scalar
        return Linear(new_slope, new_intercept)

    def evaluate(self, x):
        return self.slope * x + self.intercept
```

