class Graph:
    def __init__(self):
        self.adjacency_list = {}

    def add_edge(self, vertex1, vertex2):
        # Add edge between vertex1 and vertex2
        if vertex1 not in self.adjacency_list:
            self.adjacency_list[vertex1] = set()
        if vertex2 not in self.adjacency_list:
            self.adjacency_list[vertex2] = set()
        self.adjacency_list[vertex1].add(vertex2)
        self.adjacency_list[vertex2].add(vertex1)

    def remove_edge(self, vertex1, vertex2):
        # Remove edge between vertex1 and vertex2
        if vertex1 in self.adjacency_list and vertex2 in self.adjacency_list:
            self.adjacency_list[vertex1].discard(vertex2)
            self.adjacency_list[vertex2].discard(vertex1)

    def dfs(self, start_vertex):
        # Perform depth-first search starting from start_vertex
        dfs = DepthFirstSearch(self.adjacency_list)
        return dfs.search(start_vertex)

    def bfs(self, start_vertex):
        # Perform breadth-first search starting from start_vertex
        bfs = BreadthFirstSearch(self.adjacency_list)
        return bfs.search(start_vertex)

    def connected_components(self):
        # Find connected components in the graph
        cc = ConnectedComponents(self.adjacency_list)
        return cc.find_components()
