        headers = {'Authorization': f'Bearer {self.auth_token}'}
        url = f'{self.base_url}/{endpoint}'
        response = None
        try:
            if method == 'GET':
                response = requests.get(url, headers=headers)
            elif method == 'POST':
                response = requests.post(url, headers=headers, json=data)
            elif method == 'PUT':
                response = requests.put(url, headers=headers, json=data)
            elif method == 'DELETE':
                response = requests.delete(url, headers=headers)
            if response.status_code != 200:
                raise Exception(f'HTTP error {response.status_code}: {response.text}')
            return response.json()
        except Exception as e:
            print(f'Error making {method} request to {url}: {e}')
            return None

    def get_accounts(self):
        return self._make_request('GET', self._endpoint1)

    def manage_worker_scripts(self, method, data=None):
        return self._make_request(method, self._endpoint2, data)

    def manage_schedules(self, method, data=None):
        return self._make_request(method, self._endpoint3, data)

