def match(obj, *args):
    *paths, values = args
    current_obj = obj
    for path in paths:
        if isinstance(current_obj, dict) and path in current_obj:
            current_obj = current_obj[path]
        else:
            return False
    for key, value in values.items():
        if key not in current_obj or current_obj[key] != value:
            return False
    return True
