class FileSystem:
    def __init__(self):
        self.root = {'name': '/', 'type': 'directory', 'content': {}}
        self.current_directory = self.root

    def create_file(self, name, content):
        self.current_directory['content'][name] = {'name': name, 'type': 'file', 'content': content}

    def create_directory(self, name):
        self.current_directory['content'][name] = {'name': name, 'type': 'directory', 'content': {}}

    def get_current_directory(self):
        return self.current_directory['name']

    def change_directory(self, name):
        if name in self.current_directory['content'] and self.current_directory['content'][name]['type'] == 'directory':
            self.current_directory = self.current_directory['content'][name]

    def find_file(self, name):
        def dfs(node, path):
            if node['name'] == name and node['type'] == 'file':
                return path
            if node['type'] == 'directory':
                for child_name, child_node in node['content'].items():
                    result = dfs(child_node, path + '/' + child_name)
                    if result:
                        return result
            return None

        result = dfs(self.current_directory, self.current_directory['name'])
        return result if result else "File not found"
```

