from typing import List, Dict, Any, Tuple
import geojson

def process_data(valueLinks: List[Dict[str, Any]], record: Dict[str, Any], mappedGeometries: Dict[str, Any]) -> Tuple[Dict[str, Any], int]:
    assembled = []
    linkingDuplicateCount = 0
    seen_keys = set()

    for link in valueLinks:
        key = record.get(link['value'])
        if key in mappedGeometries:
            if key in seen_keys:
                linkingDuplicateCount += 1
            else:
                seen_keys.add(key)
            assembled.append(
                geojson.Feature(geometry=mappedGeometries[key], properties={link['value']: key})
            )

    return geojson.FeatureCollection(assembled), linkingDuplicateCount
```

