```python
class Grouping:
    def group_elements(self, elements, strategy):
        """
        Group the elements based on the specified strategy.

        Args:
        elements: A list of integers.
        strategy: A string specifying the grouping strategy ("even" or "odd").

        Returns:
        A dictionary containing the grouped elements based on the specified strategy.
        """
        grouped_elements = {'even': [], 'odd': []}

        for element in elements:
            if strategy == 'even':
                if element % 2 == 0:
                    grouped_elements['even'].append(element)
                else:
                    grouped_elements['odd'].append(element)
            elif strategy == 'odd':
                if element % 2 != 0:
                    grouped_elements['odd'].append(element)
                else:
                    grouped_elements['even'].append(element)

        return grouped_elements
```

