        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def rotate_number(n):
    n_str = str(n)
    rotations = [int(n_str[i:] + n_str[:i]) for i in range(len(n_str))]
    return rotations

def count_circular_primes(limit):
    circular_primes = set()
    for num in range(2, limit):
        if all(digit in '1379' for digit in str(num)):
            rotations = rotate_number(num)
            if all(is_prime(rotated) for rotated in rotations):
                circular_primes.update(rotations)
    return len(circular_primes)

