def checkTableTags(html: str) -> bool:
    stack = []
    i = 0
    while i < len(html):
        if html[i:i+7] == "</table":
            stack.append("</table>")
            i += 7
        elif html[i:i+6] == "<table":
            if not stack:
                return False
            stack.pop()
            i += 6
        else:
            i += 1
    return len(stack) == 0
```

