def adjust_learning_rate(optimizer, warmup_epoch, epoch, args, nums_batches):
    if args.lr_mode == 'step':
        if epoch in args.lr_step_epochs:
            new_lr = args.lr * (args.lr_decay_factor ** (epoch // args.lr_step_epochs))
            for param_group in optimizer.param_groups:
                param_group['lr'] = new_lr
    elif args.lr_mode == 'warmup_step':
        if epoch <= warmup_epoch:
            new_lr = args.lr * (epoch / warmup_epoch)
            for param_group in optimizer.param_groups:
                param_group['lr'] = new_lr
        else:
            adjusted_epoch = epoch - warmup_epoch
            if adjusted_epoch in args.lr_step_epochs:
                new_lr = args.lr * (args.lr_decay_factor ** (adjusted_epoch // args.lr_step_epochs))
                for param_group in optimizer.param_groups:
                    param_group['lr'] = new_lr
```

