            if row == 0 or board[row - 1][col] == '#':
                return board[row][col]
            if col == 0 or board[row][col - 1] == '#':
                return board[row][col]
        return ''

    def build_01_board(crosswords_lines):
        return [list(line.strip()) for line in crosswords_lines]

    head_letters = {}
    order = 1
    for i in range(len(board)):
        for j in range(len(board[0])):
            head_letters[(i, j)] = order, check_letter(i, j, board)
            order += 1
    return head_letters

