class Hict:
    def __init__(self, initial_data=None):
        if initial_data is None:
            initial_data = []
        self._keys = []
        self._values = []
        if isinstance(initial_data, dict):
            for key, value in initial_data.items():
                self[key] = value
        elif isinstance(initial_data, (list, tuple)):
            for key, value in initial_data:
                self[key] = value

    def __repr__(self):
        items = ', '.join(f'({repr(k)}, {repr(v)})' for k, v in zip(self._keys, self._values))
        return f'Hict([{items}])'

    def __setitem__(self, key, value):
        if key in self._keys:
            index = self._keys.index(key)
            self._values[index] = value
        else:
            self._keys.append(key)
            self._values.append(value)

    def __getitem__(self, key):
        if key in self._keys:
            index = self._keys.index(key)
            return self._values[index]
        else:
            raise KeyError(f'Key {key} not found')

    def __delitem__(self, key):
        if key in self._keys:
            index = self._keys.index(key)
            del self._keys[index]
            del self._values[index]
        else:
            raise KeyError(f'Key {key} not found')

    def keys(self):
        return self._keys

    def reverse_keys(self):
        return list(reversed(self._keys))

# Test the completed implementation
h = Hict()
assert repr(h) == 'Hict([])'
h['a'] = 1
h['b'] = 2
h['c'] = 3
assert repr(h) == 'Hict([(\'a\', 1), (\'b\', 2), (\'c\', 3)])'
assert h.keys() == ['a', 'b', 'c']
assert h.reverse_keys() == ['c', 'b', 'a']
```

